UPDATE MEMBER
SET FAIL_COUNT = FAIL_COUNT + 1
WHERE MEMBER_ID = #{memberId}

UPDATE MEMBER
SET FAIL_COUNT = 0
WHERE MEMBER_ID = #{memberId}

UPDATE MEMBER
SET LAST_LONG_DATE = SYSDATE
WHERE MEMBER_ID = #{memberId}

UPDATE MEMBER
SET STATUS = #{status}
WHERE MEMBER_ID = #{memberId}

